namespace SeraphimLuxury {partial class MainWindow {
 void BuildPlanningStudio14(){TitleSection("TEMPO / PLANNING","Chaque tâche, à son heure.","Votre journée se compose, puis se déroule.");var dates=new WrapPanel {Margin=new Thickness(0,8,0,22)};var picker=new DatePicker {SelectedDate=selectedDay,Width=145,Margin=new Thickness(0,0,12,8)};picker.Loaded+=delegate{foreach(var text in ToolsTests.Descend(picker).OfType<TextBox>()){text.Foreground=Visuals.Text;text.Background=Brushes.Transparent;}};picker.SelectedDateChanged+=delegate{if(picker.SelectedDate.HasValue){selectedDay=picker.SelectedDate.Value;ShowPage("Planning");}};dates.Children.Add(picker);dates.Children.Add(Small14("Aujourd’hui","◷",delegate{selectedDay=DateTime.Today;ShowPage("Planning");}));dates.Children.Add(Small14("Demain","→",delegate{selectedDay=DateTime.Today.AddDays(1);ShowPage("Planning");}));dates.Children.Add(Small14("Calendrier","▦",ShowCalendar));page.Children.Add(dates);
 var plan=Planning.Get(preferences,selectedDay);var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(1.7,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition());var body=new StackPanel {Margin=new Thickness(0,22,0,0)};var top=new Grid();top.ColumnDefinitions.Add(new ColumnDefinition());top.ColumnDefinitions.Add(new ColumnDefinition {Width=GridLength.Auto});var status=new StackPanel();status.Children.Add(Visuals.Eyebrow(selectedDay.ToString("dddd d MMMM").ToUpperInvariant()));var count=Visuals.TextBlock(plan.Tasks.Count(t=>t.Done)+" / "+plan.Tasks.Count+" terminées",12,Visuals.Muted);count.Margin=new Thickness(0,9,0,16);status.Children.Add(count);top.Children.Add(status);var actions=new StackPanel {HorizontalAlignment=HorizontalAlignment.Right};actions.Children.Add(Small14("Ajouter","+",delegate{ShowTaskEditor(plan,null);}));actions.Children.Add(Small14("Copier demain","⧉",delegate{var tomorrow=Planning.Get(preferences,selectedDay.AddDays(1));if(tomorrow.Tasks.Count>0){SetFootnote("Demain contient déjà des tâches. Elles sont conservées.");return;}foreach(var t in plan.Tasks)tomorrow.Tasks.Add(new PlanTask {Id=Guid.NewGuid().ToString("N"),Title=t.Title,Time=t.Time,AppId=t.AppId,Minutes=t.Minutes});PlanningChanged();SetFootnote("Journée copiée pour demain.");}));Grid.SetColumn(actions,1);top.Children.Add(actions);body.Children.Add(top);
 var modes=new WrapPanel {Margin=new Thickness(0,5,0,18)};modes.Children.Add(Small14(preferences.SoftPlanning?"● Soft":"○ Soft","",delegate{preferences.SoftPlanning=true;PlanningChanged();ShowPage("Planning");}));modes.Children.Add(Small14(!preferences.SoftPlanning?"● Strict":"○ Strict","",delegate{preferences.SoftPlanning=false;PlanningChanged();ShowPage("Planning");}));body.Children.Add(modes);var tasks=new WrapPanel();foreach(var item in plan.Tasks.OrderBy(t=>t.Time)){var task=item;var card=new StackPanel();var check=new CheckBox {Content=task.Title,IsChecked=task.Done,Style=(Style)Application.Current.Resources["StepCheck"],FontSize=13,Margin=new Thickness(0,0,0,18)};check.Checked+=delegate{task.Done=true;PlanningChanged();count.Text=plan.Tasks.Count(t=>t.Done)+" / "+plan.Tasks.Count+" terminées";};check.Unchecked+=delegate{task.Done=false;PlanningChanged();count.Text=plan.Tasks.Count(t=>t.Done)+" / "+plan.Tasks.Count+" terminées";};card.Children.Add(check);card.Children.Add(Visuals.TextBlock(String.IsNullOrEmpty(task.Time)?"À votre rythme":task.Time,20,Visuals.Gold));var app=preferences.Apps.FirstOrDefault(a=>a.Id==task.AppId);card.Children.Add(Visuals.TextBlock((app==null?"Journée":app.Name)+(task.Minutes>0?" · "+task.Minutes+" min":""),10,Visuals.Muted));var buttons=new WrapPanel {Margin=new Thickness(0,15,0,0)};buttons.Children.Add(Small14("Démarrer","▷",delegate{StartTask(task);}));buttons.Children.Add(Small14("Modifier","✎",delegate{ShowTaskEditor(plan,task);}));card.Children.Add(buttons);var frame=Glass14(card,new Thickness(15));frame.Width=245;frame.Margin=new Thickness(0,0,12,12);tasks.Children.Add(frame);}if(plan.Tasks.Count==0){var empty=new StackPanel {Margin=new Thickness(0,20,0,20)};empty.Children.Add(new TechnicalArt("calendar"){Width=76,Height=76,HorizontalAlignment=HorizontalAlignment.Left});empty.Children.Add(Visuals.TextBlock("Composez votre journée.",18,Visuals.Text));empty.Children.Add(Visuals.TextBlock("Une tâche. Une heure. Votre prochain pas.",11,Visuals.Muted));tasks.Children.Add(empty);}body.Children.Add(tasks);var fold=Fold13("Mes tâches","check",body,true,true);fold.Margin=new Thickness(0,0,30,16);grid.Children.Add(fold);
 var rules=new StackPanel {Margin=new Thickness(0,24,0,0)};rules.Children.Add(Branding.Eye(68,preferences.Premium,true));var state=Visuals.TextBlock(Session.Active?"SESSION ACTIVE":"EN VEILLE",11,Visuals.Gold);state.Margin=new Thickness(0,16,0,14);rules.Children.Add(state);rules.Children.Add(Visuals.TextBlock(Session.Active?(preferences.SoftPlanning?"Préparez vos tâches à l’ouverture.":"Terminez vos tâches pour ouvrir vos outils."):"Activez votre session pour appliquer les règles.",14,Visuals.Text));var caption=Visuals.TextBlock("Urgence ouvre une fois. Vos tâches restent à faire.",11,Visuals.Muted);caption.Margin=new Thickness(0,16,0,22);rules.Children.Add(caption);ToolToggle(rules,"Rappels des tâches","Pendant votre session",preferences.TaskAlerts,delegate(bool v){preferences.TaskAlerts=v;SavePreferences();},false);rules.Children.Add(Small14("Applications Travail","▦",delegate{ShowPage("Applications");}));rules.Children.Add(Small14("Aperçu du rappel","↘",delegate{ShowReminder("Votre prochain pas","Une tâche, une intention. Reprenez votre planning.");}));var right=Fold13("Règles & rappels","calendar",rules,false,true);Grid.SetColumn(right,1);grid.Children.Add(right);page.Children.Add(grid);}
